//! Constructs unverified legacy token fields and their complete wire projection.
//!
//! Fixture signatures are copied from the publication, never generated by a
//! signing API. The same ordinary fields support the private decoded-model test.

use super::core_model::{auth, cbor};
use super::support::{digest, fixed};
use alloc::{vec, vec::Vec};

/// Builds the unverified legacy authority fields and fixed ref grant.
///
/// # Panics
/// Panics if the fixed grant verb bits or pattern fail validation.
pub(super) fn authority() -> auth::Authority {
    auth::Authority {
        issuer: "issuer.example".into(),
        key_id: "k1".into(),
        subject: "ci-job".into(),
        kind: auth::PrincipalKind::Workload,
        groups: vec!["builders".into()],
        not_after: 1_760_003_600,
        not_before: None,
        token_id: core::array::from_fn(|index| u8::try_from(index + 1).unwrap()),
        grants: vec![
            auth::Grant::new("refs/heads/pr/**".into(), auth::Verbs::new(7).unwrap()).unwrap(),
        ],
        workload: None,
    }
}

/// Builds the legacy attenuation fields with the fixed ref and epoch caveats.
pub(super) fn attenuation() -> auth::Attenuation {
    auth::Attenuation {
        not_after: None,
        not_before: None,
        grants: None,
        caveats: vec![
            auth::Caveat::Ref("refs/heads/pr/1234".into()),
            auth::Caveat::Epoch("refs/heads/pr/1234".into(), 1),
        ],
    }
}

/// Reads the published next-block public key from its literal hexadecimal fixture.
///
/// # Panics
/// Panics if the literal is malformed or does not decode to 32 bytes.
pub(super) fn next_key() -> [u8; 32] {
    digest("3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c")
}

/// Reads the opaque published authority signature without signing or verification.
///
/// # Panics
/// Panics if the literal is malformed or does not decode to 64 bytes.
pub(super) fn authority_signature() -> [u8; 64] {
    fixed(concat!(
        "7239961b2b42911f2f2ad53e5b8715d82f18ba850cad724863832e43d45bbd4ccffd",
        "924ffa1189b7695a7d6c610fb766ff7ea30a26cd69924f9f140edac5f609"
    ))
}

/// Reads the opaque published attenuation signature without signing or verification.
///
/// # Panics
/// Panics if the literal is malformed or does not decode to 64 bytes.
pub(super) fn attenuation_signature() -> [u8; 64] {
    fixed(concat!(
        "3fda3b61fb042cf3fe81e027fb7968fef6f8e40fb59e7ccb98117c97392ba0bbd",
        "5aa8e92a5faf958af1cb6f61f739b5c6cec2e194e644058ea2d4f8989ac700c"
    ))
}

/// Assembles the complete legacy token wire projection from ordinary fixture fields.
///
/// # Panics
/// Panics if grant validation or key/signature fixture parsing fails, or the
/// attenuation model contains caveats other than ref and epoch.
pub(super) fn wire_projection() -> Vec<u8> {
    let authority = authority();
    let attenuation = attenuation();
    let mut bytes = vec![];
    cbor::write_array(&mut bytes, 2);
    cbor::write_map(&mut bytes, 10);
    for (key, text) in [
        (1, authority.issuer.as_str()),
        (2, authority.key_id.as_str()),
        (3, authority.subject.as_str()),
    ] {
        cbor::write_uint(&mut bytes, key);
        cbor::write_text(&mut bytes, text);
    }
    cbor::write_uint(&mut bytes, 4);
    cbor::write_uint(&mut bytes, 2);
    cbor::write_uint(&mut bytes, 5);
    cbor::write_array(&mut bytes, authority.groups.len());
    for group in &authority.groups {
        cbor::write_text(&mut bytes, group);
    }
    cbor::write_uint(&mut bytes, 6);
    cbor::write_uint(&mut bytes, authority.not_after);
    cbor::write_uint(&mut bytes, 8);
    cbor::write_bytes(&mut bytes, &authority.token_id);
    cbor::write_uint(&mut bytes, 9);
    cbor::write_array(&mut bytes, authority.grants.len());
    for grant in &authority.grants {
        cbor::write_array(&mut bytes, 2);
        cbor::write_text(&mut bytes, grant.pattern());
        cbor::write_uint(&mut bytes, u64::from(grant.verbs().bits()));
    }
    cbor::write_uint(&mut bytes, 11);
    cbor::write_bytes(&mut bytes, &next_key());
    cbor::write_uint(&mut bytes, 12);
    cbor::write_bytes(&mut bytes, &authority_signature());

    cbor::write_map(&mut bytes, 3);
    cbor::write_uint(&mut bytes, 4);
    cbor::write_array(&mut bytes, attenuation.caveats.len());
    for caveat in &attenuation.caveats {
        match caveat {
            auth::Caveat::Ref(name) => {
                cbor::write_array(&mut bytes, 2);
                cbor::write_text(&mut bytes, "ref");
                cbor::write_text(&mut bytes, name);
            }
            auth::Caveat::Epoch(name, bound) => {
                cbor::write_array(&mut bytes, 3);
                cbor::write_text(&mut bytes, "epoch");
                cbor::write_text(&mut bytes, name);
                cbor::write_uint(&mut bytes, *bound);
            }
            _ => panic!("the described legacy model has only ref and epoch caveats"),
        }
    }
    cbor::write_uint(&mut bytes, 5);
    cbor::write_bytes(&mut bytes, &next_key());
    cbor::write_uint(&mut bytes, 6);
    cbor::write_bytes(&mut bytes, &attenuation_signature());

    bytes
}
